  function parseCsv(text) {
    const rows=[];let row=[],field='',quoted=false;
    for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){field+='"';i++;}else if(ch==='"')quoted=false;else field+=ch;}else if(ch==='"')quoted=true;else if(ch===','){row.push(field);field='';}else if(ch==='\n'){row.push(field);if(row.some(x=>String(x).trim()))rows.push(row);row=[];field='';}else if(ch!=='\r')field+=ch;}
    if(quoted)throw new Error('Nieprawidłowy CSV: niedomknięty cudzysłów.');row.push(field);if(row.some(x=>String(x).trim()))rows.push(row);
    if(rows.length<2)throw new Error('CSV musi zawierać nagłówek i co najmniej jeden element.');
    const headers=rows.shift().map(x=>norm(x).replace(/\s+/g,''));
    const idx=(...keys)=>headers.findIndex(x=>keys.includes(x));
    const ref=idx('refdes','designator','ref','component','oznaczenie');const x=idx('x','xmm','posx');const y=idx('y','ymm','posy');
    if(ref<0||x<0||y<0)throw new Error('CSV wymaga kolumn refdes (lub designator), x i y.');
    const vi=idx('value','wartosc','part');const pi=idx('package','footprint','obudowa');const ni=idx('net','nets','sieć','siec');const li=idx('layer','warstwa');
    return rows.slice(0,MAX_ROWS).map((r,i)=>({refdes:clean(r[ref],40).toUpperCase(),x:Number(r[x]),y:Number(r[y]),value:clean(r[vi]||'',90),package:clean(r[pi]||'',50),net:clean(r[ni]||'',100),layer:clean(r[li]||'TOP',20)})).filter((r)=>r.refdes&&Number.isFinite(r.x)&&Number.isFinite(r.y)&&Math.abs(r.x)<100000&&Math.abs(r.y)<100000);
  }
  function parseBoardview(text,filename='boardview.csv') {
    const raw=String(text||'');if(raw.length>5*1024*1024)throw new Error('Plik Boardview jest zbyt duży do lokalnego podglądu (limit tekstu 5 MB).');
    const ext=String(filename).toLowerCase().split('.').pop();let components=[];
    if(ext==='json'){
      const obj=JSON.parse(raw);const list=Array.isArray(obj)?obj:obj.components;
      if(!Array.isArray(list))throw new Error('JSON musi zawierać tablicę components.');
      components=list.slice(0,MAX_ROWS).map(r=>({refdes:clean(r.refdes||r.designator||r.ref||r.name,40).toUpperCase(),x:Number(r.x),y:Number(r.y),value:clean(r.value||r.part||'',90),package:clean(r.package||r.footprint||'',50),net:clean(r.net||'',100),layer:clean(r.layer||'TOP',20)})).filter(r=>r.refdes&&Number.isFinite(r.x)&&Number.isFinite(r.y)&&Math.abs(r.x)<100000&&Math.abs(r.y)<100000);
    } else if(ext==='csv') components=parseCsv(raw);
    else throw new Error('Obsługiwane formaty Boardview w FIX42: CSV i JSON. Formaty producentów wymagają konwertera właściwego dla licencji i wariantu.');
    if(!components.length)throw new Error('Nie znaleziono prawidłowych pozycji z oznaczeniem i współrzędnymi x/y.');
    const seen=new Set();components=components.filter(r=>{const k=r.refdes;if(seen.has(k))return false;seen.add(k);return true;});
    return components;
  }
  function makeBoardSvg(rows) {
    if(!rows.length)return '<p class="f42-muted">Zaimportuj Boardview CSV/JSON lub otwórz planszę EDU.</p>';
    const xs=rows.map(x=>x.x),ys=rows.map(x=>x.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);
    const scaleX=v=>70+(maxX===minX?0:(v-minX)/(maxX-minX)*860);const scaleY=v=>55+(maxY===minY?0:(v-minY)/(maxY-minY)*480);
    const dots=rows.slice(0,MAX_ROWS).map((r,i)=>{const x=scaleX(r.x),y=scaleY(r.y);return `<g class="f42-board-part" data-f42-component="${esc(r.refdes)}" tabindex="0" role="button" aria-label="Element ${esc(r.refdes)}"><circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${i%7===0?10:7}" fill="${i%3===0?'#62d2bf':'#4aa8d0'}" fill-opacity=".78" stroke="#d1fbff" stroke-width="1.3"/><text x="${(x+12).toFixed(1)}" y="${(y+3).toFixed(1)}" fill="#d9f4ff" font-size="11">${esc(r.refdes)}</text></g>`;}).join('');
    return `<svg class="f42-board-svg" viewBox="0 0 1000 600" role="img" aria-label="Lokalny podgląd współrzędnych Boardview"><defs><pattern id="f42grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#39758b" stroke-opacity=".22" stroke-width="1"/></pattern></defs><rect x="12" y="12" width="976" height="576" rx="28" fill="#0a3440" stroke="#58a9b6" stroke-width="3"/><rect x="24" y="24" width="952" height="552" rx="20" fill="url(#f42grid)"/>${dots}<text x="38" y="565" fill="#8fbcc9" font-size="11">Podgląd współrzędnych z importu · nie jest schematem elektrycznym ani warstwą miedzi</text></svg>`;
  }
